-- OUTPOST UZ v1.6 — editable game data for Raid, Craft and Recycler
create table if not exists public.game_data (
  data_key text primary key check (data_key in ('raid_targets','raid_methods','craft_recipes','recycler_items','recycler_rates')),
  value jsonb not null default '[]'::jsonb,
  updated_by uuid references public.profiles(id),
  updated_at timestamptz not null default now()
);

alter table public.game_data enable row level security;
grant select on public.game_data to anon, authenticated;
grant insert, update, delete on public.game_data to authenticated;

drop policy if exists "public read game data" on public.game_data;
create policy "public read game data" on public.game_data
for select to anon, authenticated using (true);

drop policy if exists "staff manage game data" on public.game_data;
create policy "staff manage game data" on public.game_data
for all to authenticated
using (public.current_user_role() in ('super_admin','admin','editor'))
with check (public.current_user_role() in ('super_admin','admin','editor'));

